"use client";

import { useEffect, useState } from "react";

type Guide = {
  id: string;
  name: string;
  install: {
    arch?: string[];
    ubuntu?: string[];
    macos?: string[];
    windows?: string[];
  };
  verify: string[];
};

type Props = {
  techs: string[];
};

export default function Fetching({ techs }: Props) {
  const [guides, setGuides] = useState<Guide[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    async function fetchGuides() {
      try {
        const results = await Promise.all(
          techs.map(async (tech) => {
            const res = await fetch(`http://localhost:5000/${tech}`);

            if (!res.ok) {
              throw new Error(`Failed to fetch ${tech} (${res.status})`);
            }

            return res.json();
          })
        );

        setGuides(results);
      } catch (err) {
        console.error(err);
        setError("Failed to load guides.");
      } finally {
        setLoading(false);
      }
    }

    fetchGuides();
  }, [techs]);

  if (loading) {
    return <p>Loading...</p>;
  }

  if (error) {
    return <p className="text-red-500">{error}</p>;
  }

  return (
    <div className="space-y-6">
      {guides.map((guide) => (
        <div
          key={guide.id}
          className="rounded-lg border p-4 shadow"
        >
          <h2 className="text-2xl font-bold">{guide.name}</h2>

          {guide.install.arch && (
            <>
              <h3 className="mt-4 mb-2 font-semibold">
                Arch Linux
              </h3>

              {guide.install.arch.map((command, index) => (
                <pre
                  key={index}
                  className="bg-gray-900 text-green-400 p-3 rounded mb-2 overflow-x-auto"
                >
                  <code>{command}</code>
                </pre>
              ))}
            </>
          )}
        </div>
      ))}
    </div>
  );
}
